import { readFile, writeFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import express from 'express';

const __dirname = dirname(fileURLToPath(import.meta.url));
const DATA_FILE = join(__dirname, 'data', 'books.json');
const PORT = process.env.PORT || 3000;

const app = express();
app.set('view engine', 'ejs');
app.set('views', join(__dirname, 'views'));
app.use(express.urlencoded({ extended: true }));
app.use(express.static(join(__dirname, 'public')));

async function readBooks() {
  if (!existsSync(DATA_FILE)) {
    return [];
  }
  const raw = await readFile(DATA_FILE, 'utf8');
  try {
    return JSON.parse(raw || '[]');
  } catch {
    return [];
  }
}

async function writeBooks(books) {
  await writeFile(DATA_FILE, JSON.stringify(books, null, 2), 'utf8');
}

function generateId() {
  return Math.random().toString(36).slice(2, 10);
}

app.get('/', async (req, res) => {
  const books = await readBooks();
  const currentlyReading = books.filter((b) => !b.finished);
  const finished = books.filter((b) => b.finished);
  res.render('index', { currentlyReading, finished });
});

app.post('/books', async (req, res) => {
  const { title, author, notes } = req.body;
  if (!title || !title.trim()) {
    return res.status(400).send('Title is required');
  }
  const books = await readBooks();
  const newBook = {
    id: generateId(),
    title: title.trim(),
    author: (author || '').trim(),
    notes: (notes || '').trim(),
    finished: false,
  };
  books.push(newBook);
  await writeBooks(books);
  res.redirect('/');
});

app.post('/books/:id/finish', async (req, res) => {
  const books = await readBooks();
  const book = books.find((b) => b.id === req.params.id);
  if (!book) {
    return res.status(404).send('Book not found');
  }
  book.finished = true;
  await writeBooks(books);
  res.redirect('/');
});

app.get('/books/:id', async (req, res) => {
  const books = await readBooks();
  const book = books.find((b) => b.id === req.params.id);
  if (!book) {
    return res.status(404).send('Book not found');
  }
  res.render('book', { book });
});

app.listen(PORT, () => {
  console.log(`Book tracker running at http://localhost:${PORT}`);
});

