:root {
  --bg: #f7f7f5;
  --text: #222;
  --muted: #666;
  --accent: #3b6ea5;
  --accent-light: #eef4fb;
  --border: #ddd;
  --radius: 8px;
}

* {
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
  margin: 0;
  padding: 2rem 1rem;
}

.container {
  max-width: 640px;
  margin: 0 auto;
}

h1 {
  margin: 0 0 1.5rem;
  font-size: 1.75rem;
}

h2 {
  font-size: 1.25rem;
  margin: 1.5rem 0 0.75rem;
  border-bottom: 1px solid var(--border);
  padding-bottom: 0.25rem;
}

section {
  margin-bottom: 1.5rem;
}

.empty {
  color: var(--muted);
  font-style: italic;
}

.book-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.book-list li {
  display: flex;
  align-items: baseline;
  gap: 0.75rem;
  padding: 0.75rem 0;
  border-bottom: 1px solid var(--border);
}

.book-title {
  font-weight: 600;
  color: var(--text);
  text-decoration: none;
}

.book-title:hover {
  text-decoration: underline;
}

.book-author {
  color: var(--muted);
  font-size: 0.95rem;
}

.inline-form {
  margin-left: auto;
}

.add-form,
.detail-notes {
  background: #fff;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem;
}

.add-form label {
  display: block;
  margin-bottom: 1rem;
  font-weight: 500;
}

.add-form input,
.add-form textarea {
  display: block;
  width: 100%;
  margin-top: 0.25rem;
  padding: 0.5rem;
  font: inherit;
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

button {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  padding: 0.5rem 1rem;
  font: inherit;
  cursor: pointer;
}

button:hover {
  background: #2f5a88;
}

.btn-small {
  padding: 0.25rem 0.75rem;
  font-size: 0.875rem;
}

.detail-author,
.detail-status {
  margin: 0.5rem 0;
}

.detail-notes p {
  white-space: pre-wrap;
  margin: 0.5rem 0 0;
}

